// C2 — Deterministic Pre-check (v3.3 Phase 6 Sitting 1)
// Runs gates 2, 3, 4, 5, 6 in pure JS. Gates 1, 7, 8, 9, 10, 11 are deferred:
// 1, 7, 8, 9, 10 → LLM (in pending_for_llm). 11 → wired in Sitting 2 (Postgres lookup).
//
// Input:
//   $json                                  = Load Profile Context output (profile context API response)
//   $('Execute Workflow Trigger').first().json = { profile_id, job, request_meta } from caller
//
// Output: merged shape that C4 consumes to build the LLM user message.

const profileContext = $input.first().json;
const triggerInput = $('Execute Workflow Trigger').first().json;
const job = triggerInput.job ?? {};

const passed = [];
const failed = [];
const failedReasons = [];
const pending = [];

// Gate 2 — freshness (posted within 24h)
if (job.posted_at) {
  const ageHours = (Date.now() - new Date(job.posted_at).getTime()) / 3600000;
  if (ageHours <= 24) passed.push('2_freshness');
  else { failed.push('2_freshness'); failedReasons.push('Old job'); }
} else {
  pending.push('2_freshness');
}

// Gate 3 — proposal saturation (<30)
if (typeof job.proposals_count === 'number') {
  if (job.proposals_count < 30) passed.push('3_proposal_saturation');
  else { failed.push('3_proposal_saturation'); failedReasons.push('Too many invites'); }
} else {
  pending.push('3_proposal_saturation');
}

// Gate 4 — hourly floor ($25/hr min when hourly; n/a when fixed or unspecified)
if (job.budget_type === 'hourly' && typeof job.budget_min === 'number') {
  if (job.budget_min >= 25) passed.push('4_hourly_floor');
  else { failed.push('4_hourly_floor'); failedReasons.push('Low Higher rate'); }
} else {
  passed.push('4_hourly_floor');
}

// Gate 5 — client spend floor ($1000 lifetime). Sparse → pending (LLM weighs in red_flags).
if (typeof job.client_total_spent === 'number') {
  if (job.client_total_spent >= 1000) passed.push('5_client_spend_floor');
  else { failed.push('5_client_spend_floor'); failedReasons.push('Client Low spending'); }
} else {
  pending.push('5_client_spend_floor');
}

// Gate 6 — client rating floor (≥4.0). New clients with 0/null hires → pass.
if (typeof job.client_rating === 'number') {
  if (job.client_rating >= 4.0) passed.push('6_client_rating_floor');
  else { failed.push('6_client_rating_floor'); failedReasons.push('Bad rating client'); }
} else if (job.client_rating === null && (job.client_hires === null || job.client_hires === 0)) {
  passed.push('6_client_rating_floor');
} else {
  pending.push('6_client_rating_floor');
}

// LLM-only gates
pending.push('1_stack_match', '7_job_availability', '8_no_location_lockin', '9_no_video_proposal', '10_portfolio_match');

// Gate 11 — duplicate (Postgres lookup wired in Sitting 2; pending for now)
pending.push('11_no_duplicate');

return [{
  json: {
    profile_context: profileContext,
    job,
    request_meta: triggerInput.request_meta ?? {},
    deterministic: {
      passed,
      failed,
      failed_reasons: failedReasons,
      pending_for_llm: pending
    },
    criteria_version: profileContext.criteria_version ?? '0.2',
    thresholds_in_force: {
      freshness_hours: 24,
      max_proposals: 30,
      hourly_floor_usd: 25,
      client_spend_floor_usd: 1000,
      client_rating_floor: 4.0
    }
  }
}];

// C6 — Validate Output + Apply Threshold (v3.3 Phase 6 Sitting 2)
//
// Input:    $json    = parsed LLM verdict from C5 (Structured Output Parser)
// Upstream: $('Prepare Classifier Input').first().json carries profile_context, job, request_meta, criteria_version, thresholds_in_force
// Output:   unified verdict ready for C8 routing + C10 ingest

// AI Agent (no parser) emits { output: "raw text" }. Parse it as JSON; on failure, mark for review.
const raw = items[0].json;
let llmOutput;
try {
  const text = raw.output ?? raw.text ?? JSON.stringify(raw);
  // Strip optional markdown code fences (```json ... ``` or ``` ... ```)
  const stripped = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  llmOutput = JSON.parse(stripped);
} catch (e) {
  llmOutput = {
    decision: 'review',
    confidence: 0.0,
    confidence_warnings: ['parse_failure', e.message ?? 'unknown'],
    rejection_reasons: [],
    summary: `JSON parse failed on LLM output: ${(raw.output ?? '').slice(0, 200)}`,
  };
}
const upstream = $('Prepare Classifier Input').first().json;
const profileCtx = upstream.profile_context ?? {};
const reqMeta = upstream.request_meta ?? {};
const job = upstream.job ?? {};
const system = profileCtx._system ?? {};

// 1. Schema sanity — fall back to 'review' on invalid decision (do not silently default to proceed; §16.7 A1)
const ALLOWED = new Set(['proceed', 'reject', 'review']);
const verdict = { ...llmOutput };
if (!ALLOWED.has(verdict.decision)) {
  verdict.decision = 'review';
  verdict.confidence = (verdict.confidence ?? 0) * 0.5;
  verdict.confidence_warnings = [...(verdict.confidence_warnings ?? []), 'invalid_decision_value'];
}

// 2. Verifier (§16.7 A3) — regex-scan job description for gate-9 hallucinations
const description = (job.description ?? '').toLowerCase();
const VIDEO_RE = /\b(loom|video|screen[-\s]?recording|record yourself)\b/i;
if (verdict.decision === 'proceed' && VIDEO_RE.test(description)) {
  verdict.decision = 'reject';
  verdict.rejection_reasons = [...(verdict.rejection_reasons ?? []), 'Video Proposal'];
  verdict.confidence_warnings = [...(verdict.confidence_warnings ?? []), 'verifier_flipped_video'];
}

// 3. Threshold application (v3.3 §7.5)
const classifierMode = system.classifier_mode ?? 'shadow';
const minScore = system.effective_min_score ?? 50;
const totalScore = verdict.total_score ?? null;

let effectiveDecision = verdict.decision;
let thresholdFlipped = false;
if (verdict.decision === 'proceed' && totalScore !== null && totalScore < minScore) {
  effectiveDecision = 'reject';
  thresholdFlipped = true;
  verdict.rejection_reasons = [...(verdict.rejection_reasons ?? []), 'Below score threshold'];
}

