  snapshot_id: profileCtx.profile?.id ?? null,
  model: 'deterministic',
  source: reqMeta.source ?? 'auto',
  task_id: reqMeta.task_id ?? null,
  request_meta: reqMeta,
  thresholds_used: input.thresholds_in_force ?? null,
};

return [{ json: verdict }];

// C12 — Return Verdict (Phase 7 prereq)
//
// Purpose: ensure executeWorkflow callers receive the VERDICT object on the
// sub-workflow's main output, not C10's HTTP response ({ok,id}) or C11's DLQ
// response ({ok,dlq_id}).
//
// Reaches this node from two terminals:
//   - Persist Relevancy Score main[0]  (success → $json = {ok:true,id:<scoreId>})
//   - Persist to DLQ          main[0]  (DLQ      → $json = {ok:true,dlq_id:N})
//
// Verdict source priority (only one of these has run on any execution):
//   1. Build Reject Payload   — deterministic-reject OR LLM/threshold reject
//   2. Build Review Payload   — LLM review branch
//   3. Validate Output + Apply Threshold — LLM proceed branch (no rebuilder in between)
// Fallback: C5 AI Agent errored → C11 directly with no verdict ever produced.
//          Synthesize a 'review' fallback verdict so the parent can still route.

function safeNode(name) {
  try {
    const ref = $(name);
    if (ref && ref.isExecuted) {
      return ref.first().json;
    }
  } catch (e) { /* node not in execution path */ }
  return null;
}

let verdict =
  safeNode('Build Reject Payload') ||
  safeNode('Build Review Payload') ||
  safeNode('Validate Output + Apply Threshold');

if (!verdict) {
  // C5 error → C11 with no verdict. Synthesize a parent-routable fallback.
  let trigger = {};
  try { trigger = $('Execute Workflow Trigger').first().json || {}; } catch (e) {}
  const reqMeta = trigger.request_meta || {};
  verdict = {
    decision: 'review',
    effective_decision: 'review',
    threshold_flipped: false,
    rejection_reasons: [],
    gates: {},
    components: null,
    total_score: null,
    tier: 'marginal',
    confidence: 0.0,
    confidence_warnings: ['classifier_error_no_verdict'],
    proposal_angles: [],
    summary: 'Classifier errored before producing a verdict; routed to review by fallback.',
    missing_signals: [],
    profile_id: trigger.profile_id || null,
    job_external_id: (trigger.job && trigger.job.job_id) || null,
    snapshot_id: null,
    model: 'gemini-2.5-flash',
    prompt_mode: 'A_full',
    evaluation_path: 'llm',
    criteria_version: '0.2',
    prompt_version: 'v1',
    source: reqMeta.source || 'auto',
    task_id: reqMeta.task_id || null,
    request_meta: reqMeta,
    thresholds_used: null,
    classifier_mode_at_decision: 'shadow',
    min_score_at_decision: 50,
  };
}

// Stamp _score_id from C10 success leaf; null on DLQ leaf.
const inbound = (items[0] && items[0].json) || {};
const scoreId = (inbound && inbound.dlq_id == null && inbound.id != null) ? inbound.id : null;
const dlqId   = (inbound && inbound.dlq_id != null) ? inbound.dlq_id : null;

const classifierMode = verdict.classifier_mode_at_decision || 'shadow';

// Mirror classifier_mode into request_meta for parent K3 switch convenience.
// Keep both shapes: top-level classifier_mode_at_decision (existing) AND request_meta.classifier_mode (new).
const out = {
  ...verdict,
  _score_id: scoreId,
  _dlq_id: dlqId,
  request_meta: {
    ...(verdict.request_meta || {}),
    classifier_mode: classifierMode,
  },
};

return [{ json: out }];

// C6 — Validate Output + Apply Threshold (v3.3 Phase 6 Sitting 2) — DeepSeek path twin
const raw = items[0].json;
let llmOutput;
try {
  const text = raw.output ?? raw.text ?? JSON.stringify(raw);
  const stripped = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '').trim();
  llmOutput = JSON.parse(stripped);
} catch (e) {
  llmOutput = {
    decision: 'review',
    confidence: 0.0,
    confidence_warnings: ['parse_failure', e.message ?? 'unknown'],
    rejection_reasons: [],
    summary: `JSON parse failed on LLM output: ${(raw.output ?? '').slice(0, 200)}`,
  };
}
const upstream = $('Prepare Classifier Input').first().json;
const profileCtx = upstream.profile_context ?? {};
const reqMeta = upstream.request_meta ?? {};
const job = upstream.job ?? {};
const system = profileCtx._system ?? {};

const ALLOWED = new Set(['proceed', 'reject', 'review']);
const verdict = { ...llmOutput };
if (!ALLOWED.has(verdict.decision)) {
  verdict.decision = 'review';
  verdict.confidence = (verdict.confidence ?? 0) * 0.5;
  verdict.confidence_warnings = [...(verdict.confidence_warnings ?? []), 'invalid_decision_value'];
}

const description = (job.description ?? '').toLowerCase();
const VIDEO_RE = /\b(loom|video|screen[-\s]?recording|record yourself)\b/i;
if (verdict.decision === 'proceed' && VIDEO_RE.test(description)) {
  verdict.decision = 'reject';
  verdict.rejection_reasons = [...(verdict.rejection_reasons ?? []), 'Video Proposal'];
  verdict.confidence_warnings = [...(verdict.confidence_warnings ?? []), 'verifier_flipped_video'];
}

const classifierMode = system.classifier_mode ?? 'shadow';
const minScore = system.effective_min_score ?? 50;
const totalScore = verdict.total_score ?? null;

let effectiveDecision = verdict.decision;
let thresholdFlipped = false;
if (verdict.decision === 'proceed' && totalScore !== null && totalScore < minScore) {
  effectiveDecision = 'reject';
  thresholdFlipped = true;
  verdict.rejection_reasons = [...(verdict.rejection_reasons ?? []), 'Below score threshold'];
}

verdict.effective_decision           = effectiveDecision;
verdict.threshold_flipped            = thresholdFlipped;
verdict.min_score_at_decision        = minScore;
verdict.classifier_mode_at_decision  = classifierMode;

verdict.profile_id        = profileCtx.profile?.profile_id ?? null;
verdict.job_external_id   = job.job_id ?? null;
verdict.snapshot_id       = profileCtx.profile?.id ?? null;
verdict.model             = 'deepseek-r1';
verdict.prompt_mode       = 'A_full';
verdict.evaluation_path   = (upstream.deterministic?.passed?.length ?? 0) > 0
  ? 'llm_after_deterministic'
  : 'llm';
verdict.criteria_version  = verdict.criteria_version ?? upstream.criteria_version ?? '0.2';
verdict.prompt_version    = verdict.prompt_version  ?? 'v1';
verdict.source            = reqMeta.source ?? 'auto';
verdict.task_id           = reqMeta.task_id ?? null;
verdict.request_meta      = reqMeta;
verdict.thresholds_used   = upstream.thresholds_in_force ?? null;

return [{ json: verdict }];
